using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using SplifyWin;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  void VkTurnExtraSettings(Panel page){
   var p=VkTurnSettings.Load(root);var network=new StackPanel{Margin=new Thickness(0,14,0,0)};network.Children.Add(Text("БС и Wi-Fi",18));network.Children.Add(Text("Автопауза снимает системный TUN БС: трафик Windows идёт напрямую через Wi-Fi, правила VPN перестают действовать. Локальный прокси продолжает работу. Обычный VPN и независимые выходы WARP не отключаются."));
   foreach(bool any in new[]{true,false}){bool all=any;var check=new CheckBox{Name=all?"vkPauseAnyWifi":"vkPauseTrustedWifi",Content=all?"Автопауза БС на любом Wi-Fi":"Автопауза БС в доверенных сетях",IsChecked=all?p.PauseOnWifi:p.TrustedWifiEnabled};check.Click+=(s,e)=>{bool next=check.IsChecked==true;if(next&&!Confirm("В этих сетях VPN БС будет снят, трафик пойдёт напрямую. После выхода из них восстановим то же подключение, если вы его не отключили. Доверяйте только знакомым сетям: имя Wi-Fi можно подделать.","БС и Wi-Fi")){check.IsChecked=false;return;}VkTurnSettings.Update(root,v=>{if(all)v.PauseOnWifi=next;else v.TrustedWifiEnabled=next;});vkWifiCheck=DateTime.MinValue;};network.Children.Add(check);}
   var names=new TextBox{Name="vkTrustedSsids",Text=String.Join("\n",p.TrustedSsids),AcceptsReturn=true,MinHeight=75,MaxHeight=150,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};network.Children.Add(Field("Точные имена доверенных Wi-Fi · одно на строку, до 32",names));network.Children.Add(Button("Сохранить доверенные сети",()=>{var values=names.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Distinct(StringComparer.Ordinal).ToList();VkTurnSettings.Update(root,v=>v.TrustedSsids=values);vkWifiCheck=DateTime.MinValue;status.Text="Доверенные сети сохранены.";}));network.Children.Add(Text("Если Windows не сообщает имя Wi-Fi, сеть не считается доверенной. Разрешения местоположения Android здесь не требуются."));
   var stable=new CheckBox{Name="vkPreventSleep",Content="Не переводить Windows в сон при БС",IsChecked=p.PreventSleep};stable.Click+=(s,e)=>{bool next=stable.IsChecked==true;if(next&&!Confirm("Во время системного VPN БС MCRF будет просить Windows не засыпать. Экран может выключаться. Это повышает расход батареи; после отключения БС или паузы Wi-Fi запрос снимается.","Стабильность БС")){stable.IsChecked=false;return;}VkTurnSettings.Update(root,v=>v.PreventSleep=next);vkPowerCheck=DateTime.MinValue;};network.Children.Add(stable);network.Children.Add(Text("По умолчанию сон не блокируется — сбалансированный расход батареи. Настройка не меняет план электропитания Windows и не относится к обычному VPN."));page.Children.Add(Card(network));
   var masque=new StackPanel{Margin=new Thickness(0,14,0,0)};masque.Children.Add(Text("Резерв MASQUE · WDTT",18));var consent=new CheckBox{Name="vkMasqueConsent",Content="Разрешить Cloudflare MASQUE",IsChecked=p.MasqueAccepted};consent.Click+=(s,e)=>{bool next=consent.IsChecked==true;if(next&&!Confirm("MASQUE — резервный путь к TURN через Cloudflare. При первом ручном подключении создаётся отдельная регистрация Cloudflare, она сохраняется зашифрованно. Фоновые проверки регистрацию не создают. Это не WireGuard-аккаунт WARP. Условия: https://www.cloudflare.com/application/terms/", "Условия MASQUE")){consent.IsChecked=false;return;}VkTurnSettings.Update(root,v=>v.MasqueAccepted=next);};masque.Children.Add(consent);masque.Children.Add(RepositoryLink("Условия Cloudflare","https://www.cloudflare.com/application/terms/"));masque.Children.Add(Text("Согласие само по себе резерв не включает. В параметрах нужного WDTT-сервера включите MASQUE и укажите внешний SNI. Изменения применяются при следующем подключении; учётная запись не добавляется в ссылку сервера."));page.Children.Add(Card(masque));
   var servers=new StackPanel{Margin=new Thickness(0,14,0,0)};servers.Children.Add(Text("Параметры подключений",18));var available=session.State.Servers.Where(n=>TurnEngines.IsTurn(n)||n.Protocol=="qwdtt").ToArray();var selector=new ComboBox{Name="vkTurnServerSelector",ItemsSource=available,DisplayMemberPath="Name",SelectedItem=available.FirstOrDefault(n=>n.Id==session.State.SelectedServerId)??available.FirstOrDefault()};servers.Children.Add(selector);var edit=Button("Настроить подключение",()=>{var n=selector.SelectedItem as ServerNode;if(n!=null){VkTurnServerEditor(n);RefreshAfterOperation(current);}});edit.IsEnabled=available.Length>0;servers.Children.Add(edit);if(available.Length==0)servers.Children.Add(Text("Сначала импортируйте CSQTT, QWDTT или WDTT в разделе «Серверы»."));page.Children.Insert(0,Card(servers));SpaceVkTurn(page);
  }
 }
}
